def minimizeStringValue(s: str) -> str:
    # Count every letter already present in s
    freq = [0] * 26  # 26 lowercase English letters
    for c in s:
        if c != '?':
            freq[ord(c) - ord('a')] += 1

    # For each '?', greedily pick the letter with the smallest count (smallest letter on ties)
    take = [0] * 26  # how many times each letter is used to fill '?'
    for _ in range(s.count('?')):
        chosen = min(range(26), key=lambda i: freq[i])  # first (smallest) minimum
        freq[chosen] += 1
        take[chosen] += 1

    # Write the chosen letters into the '?' positions in sorted order
    result = []
    p = 0
    for c in s:
        if c != '?':
            result.append(c)
        else:
            while take[p] == 0:
                p += 1
            result.append(chr(ord('a') + p))
            take[p] -= 1

    return ''.join(result)
